const validDate=value=>typeof value==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(value)&&Number.isFinite(+parse(value))&&iso(parse(value))===value;
const current=()=>iso(new Date()),unique=(records,key=item=>String(item.id))=>{const seen=new Set();return records.filter(item=>item&&item.id!=null&&!seen.has(key(item))&&seen.add(key(item)));};
