export function workspaceUpcoming(model){const today=validDate(model.today)?model.today:current(),tasks=unique(model.tasks||[]).filter(item=>!item.done&&validDate(item.due)&&item.due>=today).map(item=>({...item,recordType:'task'}));const events=unique(model.events||[]).filter(item=>validDate(item.due)).map(item=>{let due=item.due;if(item.repeat==='yearly'){const date=parse(due),now=parse(today);let next=new Date(now.getFullYear(),date.getMonth(),date.getDate(),12);if(iso(next)<today)next=new Date(now.getFullYear()+1,date.getMonth(),date.getDate(),12);due=iso(next);}return {...item,sourceDue:item.due,due,recordType:'event',birthday:BIRTHDAY.test(item.title||'')};}).filter(item=>item.due>=today);return [...tasks,...events].sort(byDue);}
export function workspaceInbox(model){const today=validDate(model.today)?model.today:current(),messages=model.inbox||model.records||[],payments=model.finance?.payments||model.payments||[],tasks=model.tasks||[];return unique([...messages.map(item=>({...item,recordType:'inbox',group:item.type==='Дубликат'?'duplicates':item.type==='Сообщение'?'unclear':'uncategorized'})),...payments.filter(item=>item.status==='pending').map(item=>({...item,recordType:'payment',group:'payments'})),...tasks.filter(item=>!item.done&&validDate(item.due)&&item.due<today).map(item=>({...item,recordType:'task',group:'overdue'}))],item=>item.recordType+':'+item.id);}
