 connectedCallback(){if(!this._root){this.shadowRoot.innerHTML='<div class="workspace"></div><dialog class="dialog"></dialog>';this._root=this.shadowRoot.querySelector('.workspace');this._dialog=this.shadowRoot.querySelector('dialog');this._dialog.addEventListener('cancel',event=>{event.preventDefault();this._dialog.close();this._detail=null;});this.shadowRoot.addEventListener('click',event=>this.click(event));this.shadowRoot.addEventListener('input',event=>{const capture=event.composedPath().find(node=>node.hasAttribute?.('data-capture'));if(capture)this._captureText=capture.value;const search=event.composedPath().find(node=>node.localName==='flow-search');if(search){this._sessionDone.clear();this._view.query=search.value;this.reconcileContent();}});this.shadowRoot.addEventListener('change',event=>{const select=event.composedPath().find(node=>node.hasAttribute?.('data-project'));if(select){this._sessionDone.clear();this._view.project=select.value;this.reconcileContent();}});}this._stopOwners?.();this._stopOwners=observeOwners(this,()=>this.stopMotion());this.render();}
 disconnectedCallback(){this._stopOwners?.();this.stopMotion();this.closeWindows();super.disconnectedCallback();}
