 settle(requestId,result={}){const pending=this._pending.get(requestId);if(!pending||pending.epoch!==this._epoch)return false;this._pending.delete(requestId);if(result.model)this.model=result.model;const notice=this._dialog.open?this._dialog.querySelector('.notice'):this._root.querySelector('.notice');if(notice)notice.textContent=result.ok?'':result.error||'Действие не выполнено';if(result.ok&&pending.action==='capture'&&String(this._captureText||'').trim()===pending.args?.text){this._captureText='';const input=this._root.querySelector('[data-capture]');if(input)input.value='';}if(result.ok&&['inbox-task','inbox-save','inbox-archive','archive-restore','archive-purge'].includes(pending.action)){this._dialog.close();this._detail=null;}return true;}
 panel(title,body,side=''){return `<section class="panel"><div class="heading"><h2>${title}</h2>${side}</div>${body}</section>`;}
